"""
Write a class called 'Main', which accepts a list of index numbers.
The object should have an attribute called 'occupied_spaces' (length 12), 
with elements being either None or 'c'.
"""

class Main:
    def __init__(self, index_list):
        self.occupied_spaces = []
        for index in range(12):
            self.occupied_spaces.append('c' if index in index_list else None)

"""
Initialize a Car object with four attributes: color, speed, brand, worth.
"""

class Car:
    def __init__(self, color, speed):
        self.color = color
        self.speed = speed
        if color == 'brown' and speed == 'slow':
            self.brand = 'Chevrolet'
        else:
            self.brand = None
        self.worth = 'cheap' if self.brand else 'expensive'

"""
Modify the Calculator class to include 'base_number' and four math methods.
"""

class Calculator: 
    def __init__(self, base_number): 
        self.base_number = base_number 

    def add(self): 
        return int(self.base_number + 18)

    def sub(self):
        return int(self.base_number - 28)

    def mul(self): 
        return int(self.base_number * 38)

    def intdiv(self):
        return int(self.base_number // 48)
